"""Sort semantic version strings by SemVer 2.0.0 precedence."""


def _identifier_key(identifier):
    if identifier.isdigit():
        return (0, int(identifier))
    return (1, identifier)


def _version_key(version):
    core, _, build = version.partition("+")
    # Build metadata is ignored for ordering.
    release, sep, prerelease = core.partition("-")
    major, minor, patch = (int(part) for part in release.split("."))
    if sep:
        prerelease_key = tuple(_identifier_key(i) for i in prerelease.split("."))
        return (major, minor, patch, 0, prerelease_key)
    return (major, minor, patch, 1, ())


def sort_versions(vs):
    return sorted(vs, key=_version_key)
